// Map request_type to Zammad group
const groupMap = {
  'new-service':      'Sales',
  'sales':            'Sales',
  'tech-support':     'MSP Support',
  'customer-support': 'Customer Support',
  'general':          'General',
};

const body = $input.item.json.body || $input.item.json;
const requestType = body.request_type || 'general';
const group = groupMap[requestType] || 'General';

const typeLabels = {
  'new-service':      'New Service',
  'sales':            'Sales Inquiry',
  'tech-support':     'Tech Support',
  'customer-support': 'Customer Support',
  'general':          'General Question',
};
const typeLabel = typeLabels[requestType] || requestType;

const title = `[${typeLabel}] ${body.name || 'Unknown'}${
  body.business ? ` (${body.business})` : ''
}`;

const articleBody = [
  `**Request Type:** ${typeLabel}`,
  `**Name:** ${body.name || ''}`,
  body.business ? `**Business:** ${body.business}` : '',
  `**Email:** ${body.email || ''}`,
  body.phone ? `**Phone:** ${body.phone}` : '',
  body.service ? `**Service:** ${body.service}` : '',
  '',
  '**Message:**',
  body.message || '',
  '',
  '---',
  '*Submitted via kecktech.net contact form*',
].filter(l => l !== undefined && !(l === '' && false)).join('\n');

return [{
  json: {
    title,
    group,
    requestType,
    article: articleBody,
    customerEmail: body.email || '',
    customerName: body.name || '',
  }
}];
